    /// <summary>
    /// Returns a Case Number for each of the StepAP214 Entities
    /// </summary>
    public override int TypeNumber(Type atype)
    {
        if (Types.IsBound(atype))
        {
            return Types.Find(atype);
        }
        else
        {
            return 0;
        }
    }

    public override string SchemaName(InterfaceModel model)
    {
        StepModel model1 = model as StepModel;
        Parameters.WriteMode_StepSchema schema = model1 is null ? Parameters.WriteMode_StepSchema.WriteMode_StepSchema_AP214IS
                                                                          : model1.InternalParameters.WriteSchema;
        switch (schema)
        {
            case Parameters.WriteMode_StepSchema.WriteMode_StepSchema_AP203:
                return SchemaAP203;
            case Parameters.WriteMode_StepSchema.WriteMode_StepSchema_AP214IS:
                return SchemaAP214IS;
            case Parameters.WriteMode_StepSchema.WriteMode_StepSchema_AP242DIS:
                return SchemaAP242DIS;
            case Parameters.WriteMode_StepSchema.WriteMode_StepSchema_AP214CD:
                return SchemaAP214CD;
            case Parameters.WriteMode_StepSchema.WriteMode_StepSchema_AP214DIS:
            default:
                return SchemaAP214DIS;
        }
    }

    /// <summary>
    /// Returns count of Protocol used as Resources (level one)
    /// </summary>
    public override int ResourceCount
    {
        get
        {
            return 1;
        }
    }

    /// <summary>
    /// Returns a Resource, given its rank (between 1 and NbResources)
    /// </summary>
    public override Protocol Resource(int num)
    {
        return global::Kerf.Engine.Exchange.Step.Header.HeaderSection.Protocol();
    }
